#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct { void *items; size_t cap, head, tail, count; bool closed;
                 pthread_mutex_t m;
                 pthread_cond_t  not_empty;   /* waiters: 'something to read' */
                 pthread_cond_t  not_full;    /* waiters: 'room to write' */
               } chan_t;   /* the two condvars are what a Go channel actually is */

void chan_send(chan_t *c, void *v) {
    pthread_mutex_lock(&c->m);
    while (c->count == c->cap && !c->closed)   /* while, not if: spurious wakeups */
        pthread_cond_wait(&c->not_full, &c->m);
    if (c->closed) { pthread_mutex_unlock(&c->m); return; }   /* send-after-close */
    c->items[c->head] = v;
    c->head = (c->head + 1) % c->cap;
    c->count++;
    pthread_cond_signal(&c->not_empty);         /* wake a reader */
    pthread_mutex_unlock(&c->m);
}

void chan_recv(chan_t *c, void *out) {   /* false when closed and drained */
    pthread_mutex_lock(&c->m);
    while (c->count == 0 && !c->closed)
        pthread_cond_wait(&c->not_empty, &c->m);
    if (c->count == 0) { pthread_mutex_unlock(&c->m); return false; }
    *out = c->items[c->tail];
    c->tail = (c->tail + 1) % c->cap;
    c->count--;
    pthread_cond_signal(&c->not_full);
    pthread_mutex_unlock(&c->m);
}

void chan_close(chan_t *c) {              /* the SENDER closes: broadcast wakes all */
    pthread_mutex_lock(&c->m); c->closed = true;
    pthread_cond_broadcast(&c->not_empty);  /* broadcast, not signal: wake every reader */
    pthread_mutex_broadcast(&c->not_full);
    pthread_mutex_unlock(&c->m);
}
/* select == timed wait or poll; there is no built-in. Use a timed wait or a
   dedicated 'done' flag. For SPSC with no blocking, use a lock-free ring. */
